        want_r = -sum(dr for dr, dc, n in arms)
        want_c = -sum(dc for dr, dc, n in arms)

    choices = []
    for color in set(v for row in grid for v in row):
        if color in (bg, marker_color):
            continue
        for comp in components(color):
            cy = sum(r for r, c in comp) / len(comp)
            cx = sum(c for r, c in comp) / len(comp)
            if (cy - er) * want_r <= 0 or (cx - ec) * want_c <= 0:
                continue
            d = min(abs(r-er) + abs(c-ec) for r, c in comp)
            choices.append((d, comp))

    out = [row[:] for row in grid]
    if choices:
        target = min(choices, key=lambda x: x[0])[1]
        for r, c in target:
            out[r][c] = marker_color
    return out
